//! Aggregated capability manifest + proxy allowlist for lan-webui.
//!
//! Both artifacts are generated by `scripts/gen_capabilities.py --aggregate`
//! from `modules.yaml` (the backend's source of truth for which modules the
//! frontend renders) and the per-component `capabilities.<name>.sample.json`.
//! They are embedded at compile time; `validate()` guards against the generator
//! drifting from `modules.yaml` so a stale `cargo build` fails loudly.

/// Single-file frontend artifact, shared with `lan-mdns` (D-M7-3).
pub const INDEX_HTML: &str = include_str!("../../common/webui/src/assets/index.html");
/// Aggregated capability manifest for the frontend (`window.__LAN_CAPABILITIES__`).
pub const AGGREGATE_JSON: &str = include_str!("../capabilities.json");
/// `name|path` lines guarding the same-origin proxy; no Rust JSON parser needed.
pub const AGGREGATE_ALLOWLIST: &str = include_str!("../capabilities.allowlist.txt");

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Component {
    pub name: String,
    pub label: String,
    pub port: u16,
    pub icon: String,
    pub tone: String,
}

#[derive(Clone, Debug, Default)]
pub struct Modules {
    pub version: u64,
    pub port: u16,
    pub components: Vec<Component>,
    pub libs: Vec<String>,
}

fn split_kv(text: &str) -> Option<(&str, String)> {
    let (key, rest) = text.split_once(':')?;
    let mut value = rest.trim().to_string();
    if let Some(pos) = value.find(" #") {
        value.truncate(pos);
    }
    Some((
        key.trim(),
        value
            .trim()
            .trim_matches('"')
            .trim_matches('\'')
            .trim()
            .to_string(),
    ))
}

fn parse_u16(value: &str) -> Option<u16> {
    value.parse::<u16>().ok()
}

/// Minimal line-based reader for `lan-webui/modules.yaml`. Mirrors the shape
/// of `shell/components.yaml` so the two manifests stay consistent.
pub fn parse_modules(text: &str) -> Result<Modules, String> {
    let mut out = Modules::default();
    let mut current: Option<Component> = None;
    let mut in_libs = false;
    for raw in text.lines() {
        let trimmed = raw.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if trimmed == "enabled_components:" {
            in_libs = false;
            continue;
        }
        if trimmed == "libs:" {
            in_libs = true;
            continue;
        }
        if in_libs {
            if let Some(lib) = trimmed.strip_prefix("- ") {
                let lib = lib.trim();
                if !lib.is_empty() {
                    out.libs.push(lib.to_string());
                }
            }
            continue;
        }
        if let Some(value) = trimmed.strip_prefix("- name:") {
            if let Some(item) = current.take() {
                out.components.push(item);
            }
            let name = value.trim().to_string();
            current = Some(Component {
                name: name.clone(),
                label: name,
                port: 0,
                icon: "cube".to_string(),
                tone: "blue".to_string(),
            });
            continue;
        }
        // Nested list items that are not component entries are skipped.
        if trimmed.starts_with("- ") {
            continue;
        }
        let (key, value) = match split_kv(trimmed) {
            Some(pair) => pair,
            None => continue,
        };
        if let Some(item) = current.as_mut() {
            match key {
                "name" => item.name = value.clone(),
                "label" => item.label = value,
                "port" => {
                    item.port = parse_u16(&value)
                        .ok_or_else(|| format!("invalid port for {}", item.name))?;
                }
                "icon" => item.icon = value,
                "tone" => item.tone = value,
                _ => {}
            }
        } else {
            match key {
                "version" => out.version = value.parse::<u64>().unwrap_or(1),
                "port" => out.port = parse_u16(&value).unwrap_or(8090),
                _ => {}
            }
        }
    }
    if let Some(item) = current.take() {
        out.components.push(item);
    }
    Ok(out)
}

/// Compile-time manifest vs. generated manifest sanity check (D-M7-1).
///
/// The strong check (schema + backend route drift) lives in
/// `scripts/gen_capabilities.py`; here we only assert the embedded aggregate
/// mentions every enabled component and the `lan-webui` identity, so a stale
/// generated file is caught without a JSON parser.
pub fn validate(modules: &Modules) -> Result<(), String> {
    if modules.components.is_empty() {
        return Err("modules.yaml declares no enabled component".to_string());
    }
    for c in &modules.components {
        if c.port == 0 {
            return Err(format!("module {} has no port", c.name));
        }
        if !AGGREGATE_JSON.contains(&format!("\"{}\"", c.name)) {
            return Err(format!(
                "aggregate manifest missing enabled component {}",
                c.name
            ));
        }
    }
    if !AGGREGATE_JSON.contains("\"component\":\"lan-webui\"")
        && !AGGREGATE_JSON.contains("\"component\": \"lan-webui\"")
    {
        return Err("aggregate manifest is not for lan-webui".to_string());
    }
    Ok(())
}

/// Counts used by the status endpoint (no JSON parser needed).
pub fn module_count() -> usize {
    AGGREGATE_JSON.matches("\"panels\"").count()
}

pub fn allowlist_has(name: &str, path: &str) -> bool {
    let key = format!("{name}|{path}");
    AGGREGATE_ALLOWLIST.lines().any(|line| line == key)
}

#[cfg(test)]
mod tests {
    use super::*;

    const SAMPLE: &str = "\
version: 1
port: 8090
enabled_components:
  - name: lan-mdns
    label: 名称解析与服务发现
    port: 8080
    icon: dns
    tone: blue
  - name: lan-hosts
    port: 8084
libs:
  - common-probe
";

    #[test]
    fn parses_enabled_components_and_libs() {
        let m = parse_modules(SAMPLE).unwrap();
        assert_eq!(m.components.len(), 2);
        assert_eq!(m.components[0].name, "lan-mdns");
        assert_eq!(m.components[0].port, 8080);
        assert_eq!(m.components[0].label, "名称解析与服务发现");
        assert_eq!(m.components[1].name, "lan-hosts");
        assert_eq!(m.components[1].tone, "blue"); // default filled in
        assert_eq!(m.libs, vec!["common-probe".to_string()]);
    }

    #[test]
    fn defaults_port_to_zero_then_fails_validate() {
        let text = "enabled_components:\n  - name: demo\n";
        let m = parse_modules(text).unwrap();
        assert_eq!(m.components[0].port, 0);
        assert!(validate(&m).is_err());
    }

    #[test]
    fn allowlist_lookup_is_exact() {
        // lan-mdns|/api/records is declared; a fabricated path is not.
        assert!(allowlist_has("lan-mdns", "/api/records"));
        assert!(!allowlist_has("lan-mdns", "/api/does-not-exist"));
    }
}
